  --mu-r-glass-face-code-screen-reach: 1.2px;
  /* hover-engraving: reference style.css .meta, .meta .eng b, .meta .led, .meta .derived-tags span */
  --mu-r-hover-engraving-led-shadow:
    /* mu-recipe:hover-engraving:14 */ 0 0 0 .5px rgba(0,0,0,.25);
  --mu-r-hover-engraving-self-height: 22px;
  --mu-r-hover-engraving-self-pad: 10px;
  --mu-r-hover-engraving-self-gap: 8px;
  --mu-r-hover-engraving-self-blur: blur(12px);
  --mu-r-hover-engraving-self-dwell: 420ms;
  --mu-r-hover-engraving-self-rise: 2px;
  --mu-r-hover-engraving-self-slide: 3px;
  --mu-r-hover-engraving-self-beside-gap: 4px;
  --mu-r-hover-engraving-self-beside-top: 9px;
  --mu-r-hover-engraving-self-below-gap: 8px;
  --mu-r-hover-engraving-self-fade: 160ms;
  --mu-r-hover-engraving-self-move: 200ms;
  --mu-r-hover-engraving-emphasis-weight: 500;
  --mu-r-hover-engraving-tag-font: 400 9px/15px var(--mu-mono);
  --mu-r-hover-engraving-tag-tracking: 0.06em;
  --mu-r-hover-engraving-tag-height: 15px;
  --mu-r-hover-engraving-tag-pad: 6px;
  --mu-r-hover-engraving-tag-gap: 4px;
  --mu-r-hover-engraving-led-size: 5px;
  --mu-r-hover-engraving-led-gap: 4px;
  --mu-r-hover-engraving-led-lift: 1px;
}
/* Layers in an object's own colour resolve where --mu-self is set (data-mu-self on the object). */
[data-mu-self] {
  --mu-r-swatch-self-background:
    linear-gradient(135deg, rgba(255,255,255,.22), rgba(255,255,255,0) 45%, rgba(0,0,0,.10)),
    color-mix(in srgb, var(--mu-self) 100%, transparent);
  --mu-r-swatch-self-shadow:
    inset 0 1px 0 rgba(255,255,255,.45),
    inset 0 -1.5px 0 rgba(0,0,0,.18),
    inset 0 0 6px 2px rgba(255,255,255,.12),
    0 1px 2px rgba(0,0,0,.12),
    0 14px 26px -12px color-mix(in srgb, var(--mu-self) 53%, transparent);
  --mu-r-glass-face-link-screen-background:
    radial-gradient(120% 90% at 85% 0%, color-mix(in srgb, var(--mu-self) 100%, transparent) 0%, #121316 70%);
}
